from collections import deque

def transform(grid):
    g=[row[:] for row in grid]; H=len(g); W=len(g[0])
    hlines=[r for r in range(H) if g[r] and all(x==g[r][0] and x!=0 for x in g[r])]
    def cell_bounds(r):
        top=max([h for h in hlines if h<r], default=-1)
        bot=min([h for h in hlines if h>r], default=H)
        return top,bot
    # components of same color (excluding hline rows)
    seen=set(); comps=[]
    for r in range(H):
        if r in hlines: continue
        for c in range(W):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; q=deque([(r,c)]); seen.add((r,c)); pix=[]
                while q:
                    a,b=q.popleft(); pix.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and na not in hlines and g[na][nb]==col and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                comps.append((col,pix))
    def mirror_targets(pix):
        # candidate (r',c) fills keyed by direction
        res={'up':[], 'down':[]}
        for (r,c) in pix:
            top,bot=cell_bounds(r)
            for d,gl in (('up',top),('down',bot)):
                if gl<0 or gl>=H: continue
                rp=2*gl-r
                if 0<=rp<H and rp not in hlines and g[rp][c]==0:
                    res[d].append((rp,c))
        return res
    fills=[]
    for col,pix in comps:
        tg=mirror_targets(pix)
        has={'up':len(tg['up'])>0,'down':len(tg['down'])>0}
        # existing mirror check: every pixel has same-color mirror across some adjacent line -> complete
        def existing(r,c):
            top,bot=cell_bounds(r)
            for gl in (top,bot):
                if 0<=gl<H:
                    rp=2*gl-r
                    if 0<=rp<H and rp not in hlines and g[rp][c]==col: return True
            return False
        complete=all(existing(r,c) for r,c in pix)
        if complete: continue
        cands=[d for d in ('up','down') if has[d]]
        if not cands: continue
        if len(cands)==1: d=cands[0]
        else:
            # alignment: compare with complete same-color figures' extents
            refs=[]
            for c2,p2 in comps:
                if c2==col and p2 is not pix and all(existing(r,c) for r,c in p2):
                    refs.append((min(r for r,_ in p2), max(r for r,_ in p2)))
            ext=lambda dd:(min(r for r,_ in tg[dd]+pix), max(r for r,_ in tg[dd]+pix))
            d=None
            for dd in ('up','down'):
                for rmin,rmax in refs:
                    e=ext(dd)
                    if e[0]==rmin or e[1]==rmax: d=dd; break
                if d: break
            if not d: d='down'
        fills+= tg[d]
    for r,c in fills: g[r][c]=g[r][c] or next(col for col,pix in comps if (r,c) in [(rr,cc) for rr,cc in pix]) if False else None
    # need color for fills: recompute per component
    g=[row[:] for row in grid]
    for col,pix in comps:
        tg=mirror_targets(pix)
        def existing(r,c):
            top,bot=cell_bounds(r)
            for gl in (top,bot):
                if 0<=gl<H:
                    rp=2*gl-r
                    if 0<=rp<H and rp not in hlines and g[rp][c]==col: return True
            return False
        if all(existing(r,c) for r,c in pix): continue
        cands=[d for d in ('up','down') if tg[d]]
        if not cands: continue
        if len(cands)==1: d=cands[0]
        else:
            refs=[]
            for c2,p2 in comps:
                if c2==col and p2 is not pix and all(existing(r,c) for r,c in p2):
                    refs.append((min(r for r,_ in p2), max(r for r,_ in p2)))
            ext=lambda dd:(min(r for r,_ in tg[dd]+pix), max(r for r,_ in tg[dd]+pix))
            d=None
            for dd in ('up','down'):
                for rmin,rmax in refs:
                    e=ext(dd)
                    if e[0]==rmin or e[1]==rmax: d=dd; break
                if d: break
            if not d: d='down'
        for r,c in tg[d]: g[r][c]=col
    return g

