def transform(grid):
    g=[row[:] for row in grid]; H,W=len(g),len(g[0])
    hlines=[r for r in range(H) if g[r] and all(x==g[r][0] and x!=0 for x in g[r])]
    def conn_comps():
        seen=set(); out=[]
        for r in range(H):
            if r in hlines: continue
            for c in range(W):
                if g[r][c] and (r,c) not in seen:
                    col=g[r][c]; st=[(r,c)]; seen.add((r,c)); pix=[]
                    while st:
                        a,b=st.pop(); pix.append((a,b))
                        for da in(-1,0,1):
                            for db in(-1,0,1):
                                na,nb=a+da,b+db
                                if 0<=na<H and 0<=nb<W and na not in hlines and g[na][nb]==col and (na,nb) not in seen:
                                    seen.add((na,nb)); st.append((na,nb))
                    out.append((col,pix))
        return out
    comps=conn_comps()
    def lineabove(r): return max([h for h in hlines if h<r], default=None)
    def linebelow(r): return min([h for h in hlines if h>r], default=None)
    def mirrors(pix):  # existing same-color mirror pixels
        s=set()
        for (r,c) in pix:
            for gl in (lineabove(r),linebelow(r)):
                if gl is not None:
                    rp=2*gl-r
                    if 0<=rp<H and rp not in hlines and g[rp][c]==col_of(pix): s.add((rp,c))
        return s
    def col_of(pix): return g[pix[0][0]][pix[0][1]]
    def targets(pix, d):  # candidate fills for direction
        t=[]
        for (r,c) in pix:
            gl = lineabove(r) if d=='up' else linebelow(r)
            if gl is None: return None
            rp=2*gl-r
            if not (0<=rp<H) or rp in hlines or g[rp][c]!=0: return None
            t.append((rp,c))
        return t
    fills=[]
    for col,pix in comps:
        ps=set(pix); mir=mirrors(pix)
        if mir:  # complete (has mirror): skip; full figure extent = pix|mir
            continue
        ext_full=lambda comp: { (r,c) for r,c in comp } 
        # reference: complete same-color figures' full extents
        refs=[]
        for c2,p2 in comps:
            if c2!=col: continue
            m2=mirrors(p2)
            if m2:
                allp=p2+list(m2)
                refs.append((min(r for r,_ in allp), max(r for r,_ in allp)))
        tu,td=targets(pix,'up'),targets(pix,'down')
        cands=[(d,t) for d,t in (('up',tu),('down',td)) if t]
        if not cands: continue
        if len(cands)==1: d,t=cands[0]
        else:
            d=None
            for dd,t in cands:
                e=(min(r for r,_ in t+pix), max(r for r,_ in t+pix))
                if any(e[0]==rmin or e[1]==rmax for rmin,rmax in refs): d,t=d or dd,t; d=dd; break
            if d is None: d,t='down',td
        fills+= [(col,r,c) for r,c in t]
    for col,r,c in fills: g[r][c]=col
    return g

